  ('47bdf033-56ae-4f66-b078-3408a4cb75b3', '068ae52f-76ef-4aa4-bda0-ca03451683be', 2,
   '[{"domain": "Reproductie", "subdomain": "Erfelijke eigenschap"}]'::jsonb,
