   '["enzymwerking", "pH-optimum", "lysosomen", "fagosoom", "afbraak bacteriën"]'::jsonb,
   $$Verklaren dat lysosomale enzymen bij een verhoogde pH minder goed werken waardoor de bacterie niet wordt afgebroken.$$,
   $$biologie-havo-2023-ii-tuberculose-bacterie-speelt-verstoppertje-vraag11.png$$, $$1p 11 Verklaar waardoor de bacteriën niet worden afgebroken als de pH in het fagosoom verandert.$$, array['91042618-a8a9-438b-b92f-2cb1c44fc195', 'ed1ec934-fbf0-49d2-a904-4079b397f882']::uuid[]),
