   $$biologie-havo-2023-ii-terug-naar-de-mammoetsteppe-vraag17.png$$, $$1p 17 Verklaar hoe een verschil in enkele nucleotiden in het hemoglobine-gen leidt tot een afwijkend hemoglobine-eiwit.$$, array['d994b377-2b2e-42d4-8367-5cc1d63cdc55']::uuid[]),
  ('f4c8f571-2f8a-4b42-8f5a-45260ec647ba', 'a80a18d7-9c2f-4a1e-bca2-c4fdbab548d5', 18,
