   $$biologie-havo-2023-ii-terug-naar-de-mammoetsteppe-vraag18.png$$, $$2p 18 Beredeneer hoe evolutie heeft geleid tot afwijkende hemoglobine bij mammoeten.$$, array['d994b377-2b2e-42d4-8367-5cc1d63cdc55', '877fa397-9026-405d-b455-5dbe0469ce41']::uuid[]),
  ('03a85550-fb68-467d-8041-1676ec9585e1', 'a80a18d7-9c2f-4a1e-bca2-c4fdbab548d5', 19,
   '[{"domain": "Evolutie", "subdomain": "Soortvorming"}, {"domain": "Evolutie", "subdomain": "Selectie"}]'::jsonb,
