   $$biologie-havo-2023-ii-witte-haai-wordt-zelf-prooi-vraag21.png$$, $$2p 21 Schrijf de nummers 1, 2 en 3 onder elkaar en noteer erachter of de betreffende uitspraak juist of onjuist is.$$, array['67caf0de-29cd-4ca4-b0ce-7ee99714e8a0']::uuid[]),
  ('6cf8aaf6-f7a2-4e65-9144-80a6f765be48', '5e22545c-d737-4954-8cf1-9313da8e13a0', 22,
