   '["energieberekening", "energiebehoefte", "energiestroom", "rekenen met gegevens", "voedselketen"]'::jsonb,
   $$Berekenen hoeveel dagen een orka in zijn energiebehoefte kan voorzien met de energie uit een haaienlever.$$,
